//! The UVM commands a guest may send, and where their descriptors sit.
//!
//! `/dev/nvidia-uvm` is a second ioctl interface with its own numbering and
//! its own parameter structs. RM's privilege machinery does not reach it:
//! `uvm_ioctl.h` carries no flags word, so there is nothing here resembling
//! [`crate::rmallow`]'s reading of what an unprivileged caller may do. What a
//! table can say is what each call *is* -- its number, its exact size, and
//! where in it a file descriptor sits -- and that is what this one says.
//!
//! Generated by `gen/uvm_extract.py`, which compiles a probe against each
//! release's own headers. Every offset is an `offsetof` and every size a
//! `sizeof`; nothing here was counted by hand.
//!
//! # Why the descriptors matter
//!
//! Several UVM calls carry a file descriptor inside their parameters. A
//! descriptor is a number in one process's table and nothing at all in
//! another's, so a guest's `rmCtrlFd` forwarded untouched names whichever of
//! the backend's files happens to sit at that number. The backend has to find
//! it, replace it with its own, and check it is a file this VM opened.
//!
//! The handle beside it is the same problem one level up. UVM passes
//! `{rmCtrlFd, hClient}` together: the descriptor says which RM client to look
//! in and the handle indexes it. Translating the descriptor and forwarding the
//! guest's handle would name an object in the backend's client rather than the
//! guest's, so [`FdSlot::handle`] records where that handle is for the calls
//! that have one.

pub mod v535_129_03;
pub mod v580_178_04;
pub mod v595_104_02;
pub mod v595_71_05;
pub mod v615_71_09;

use crate::version::DriverVersion;

/// What a descriptor inside a UVM parameter block refers to.
///
/// These are not interchangeable, and the backend must not treat a descriptor
/// as valid merely because it is one of this VM's: a call wanting `nvidiactl`
/// handed a UVM file is a different call than the one UVM will act on.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Fd {
    /// `/dev/nvidiactl`, the RM control device.
    Ctl,
    /// `/dev/nvidia-uvm` itself.
    Uvm,
    /// Something this backend did not open -- a dma-buf. There is no handle
    /// of ours behind it and nothing to translate it to.
    Foreign,
}

/// One descriptor inside a parameter block, and the handle that goes with it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct FdSlot {
    pub kind: Fd,
    /// Byte offset of the `NvS32` descriptor.
    pub at: usize,
    /// Byte offset of the `NvHandle` the descriptor indexes, when there is
    /// one. `UVM_IMPORT_DMA_BUF` carries a descriptor and no handle.
    pub handle: Option<usize>,
}

impl FdSlot {
    pub const fn new(kind: Fd, at: usize, handle: Option<usize>) -> Self {
        Self { kind, at, handle }
    }
}

/// One UVM command.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct UvmCmd {
    pub num: u32,
    /// `sizeof` the parameter struct. Zero for a command that takes none.
    pub params_size: u32,
    pub fds: &'static [FdSlot],
}

impl UvmCmd {
    pub const fn new(num: u32, params_size: u32, fds: &'static [FdSlot]) -> Self {
        Self {
            num,
            params_size,
            fds,
        }
    }
}

/// The `UVM_INIT_FLAGS_*` one release defines.
///
/// `None` is a flag the release does not have, which is a different thing from
/// a flag it has and leaves clear. 535.129.03 has no
/// `UVM_INIT_FLAGS_DISABLE_PAGEABLE_ACCESS` at all -- its mask is `0x3`, not
/// `0x7` -- so on that release there is no bit to ask with and the backend has
/// to establish the same thing another way.
///
/// `disable_hmm` and `disable_pageable_migrations` are the same bit under two
/// names. That is not a mistake in the generator: 615.71.09 defines both as
/// `0x1`, having renamed what the bit means while keeping the old spelling.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct InitFlags {
    pub disable_hmm: Option<u64>,
    pub multi_process_sharing_mode: u64,
    pub disable_pageable_access: Option<u64>,
    pub disable_pageable_migrations: Option<u64>,
    pub mask: u64,
}

impl InitFlags {
    /// What the backend sends, whatever the guest asked for.
    ///
    /// HMM off, because it maps host memory the guest has no claim to; sharing
    /// mode on, because the backend holds one UVM file for a guest whose
    /// processes each believe it is theirs; pageable access off where the
    /// release has a bit for it.
    pub const fn ours(&self) -> u64 {
        let mut f = self.multi_process_sharing_mode;
        if let Some(b) = self.disable_hmm {
            f |= b;
        }
        if let Some(b) = self.disable_pageable_access {
            f |= b;
        }
        f
    }

    /// Whether this release can be told to refuse pageable access outright.
    ///
    /// When it cannot, [`Selected::pageable_must_be_off`] is what the backend
    /// has to fall back on.
    pub const fn can_disable_pageable_access(&self) -> bool {
        self.disable_pageable_access.is_some()
    }
}

struct Profile {
    version: DriverVersion,
    /// A function rather than the slice, for the reason given in
    /// [`crate::rmctrl`]: a static read in another static's initializer is
    /// const-evaluated and the table can end up copied per use.
    cmd: fn() -> &'static [UvmCmd],
    init: fn() -> InitFlags,
}

/// Profiles in ascending version order.
static PROFILES: &[Profile] = &[
    Profile {
        version: DriverVersion::new(535, 129, 3),
        cmd: || v535_129_03::CMD,
        init: || v535_129_03::INIT,
    },
    Profile {
        version: DriverVersion::new(580, 178, 4),
        cmd: || v580_178_04::CMD,
        init: || v580_178_04::INIT,
    },
    Profile {
        version: DriverVersion::new(595, 71, 5),
        cmd: || v595_71_05::CMD,
        init: || v595_71_05::INIT,
    },
    Profile {
        version: DriverVersion::new(595, 104, 2),
        cmd: || v595_104_02::CMD,
        init: || v595_104_02::INIT,
    },
    Profile {
        version: DriverVersion::new(615, 71, 9),
        cmd: || v615_71_09::CMD,
        init: || v615_71_09::INIT,
    },
];

/// The UVM table for one host release.
#[derive(Clone, Copy)]
pub struct Selected {
    pub cmd: &'static [UvmCmd],
    pub init: InitFlags,
    /// The host release has a table of its own. When false this is an older
    /// release's, and what it says about a newer one is an assumption.
    pub exact: bool,
}

/// The table for a host driver version: its own, or the nearest older one.
pub fn select(v: DriverVersion) -> Option<Selected> {
    PROFILES
        .iter()
        .rev()
        .find(|p| p.version <= v)
        .map(|p| Selected {
            cmd: (p.cmd)(),
            init: (p.init)(),
            exact: p.version == v,
        })
}

fn find(table: &'static [UvmCmd], num: u32) -> Option<&'static UvmCmd> {
    table
        .binary_search_by_key(&num, |c| c.num)
        .ok()
        .map(|i| &table[i])
}

impl Selected {
    /// The entry for this command, if every table that has to agree does.
    ///
    /// On an exact table this is a lookup. On an older one every release has
    /// to describe the command identically -- same size, same descriptors in
    /// the same places. A parameter struct that gained a field moves every
    /// descriptor after it, and a backend reading a descriptor at the wrong
    /// offset reads whatever the guest put there, so disagreement here is not
    /// a detail to paper over.
    pub fn entry(&self, num: u32) -> Option<&'static UvmCmd> {
        let e = find(self.cmd, num)?;
        if self.exact {
            return Some(e);
        }
        PROFILES
            .iter()
            .all(|p| find((p.cmd)(), num).is_some_and(|o| o == e))
            .then_some(e)
    }

    /// Whether the backend must prove pageable access is off rather than ask
    /// for it.
    ///
    /// Before 615.71.09 there is no `DISABLE_PAGEABLE_ACCESS` bit, so
    /// `UVM_INITIALIZE` cannot carry the request. On those releases the
    /// backend asks `UVM_PAGEABLE_MEM_ACCESS` instead and refuses the file
    /// unless the answer is no: pageable access lets the GPU fault on host
    /// memory the guest never registered, which is the whole thing this is
    /// meant to prevent.
    pub const fn pageable_must_be_off(&self) -> bool {
        !self.init.can_disable_pageable_access()
    }

    /// The flags word the backend sends for `UVM_INITIALIZE`.
    pub const fn init_flags(&self) -> u64 {
        self.init.ours()
    }
}

/// The versions with tables of their own, ascending.
pub fn supported_versions() -> impl Iterator<Item = DriverVersion> {
    PROFILES.iter().map(|p| p.version)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn v(a: u32, b: u32, c: u32) -> DriverVersion {
        DriverVersion::new(a, b, c)
    }

    #[test]
    fn tables_are_sorted_and_unique() {
        for p in PROFILES {
            let t = (p.cmd)();
            assert!(!t.is_empty(), "{}", p.version);
            assert!(
                t.windows(2).all(|w| w[0].num < w[1].num),
                "{} is not sorted by command number",
                p.version
            );
        }
    }

    /// Every descriptor and every handle has to lie inside the struct it is
    /// an offset into. An offset past the end is a read of whatever follows
    /// the parameter block.
    /// The wire format the backend publishes to the guest has room for one
    /// descriptor per command. Nothing in UVM promises that, so it is asserted
    /// here: a release that brings a second makes this fail rather than making
    /// the guest quietly drop one.
    #[test]
    fn a_uvm_command_carries_at_most_one_descriptor() {
        for p in PROFILES {
            for c in (p.cmd)() {
                assert!(
                    c.fds.len() <= 1,
                    "{}: {:#x} carries {} descriptors; the guest is told of one",
                    p.version,
                    c.num,
                    c.fds.len()
                );
            }
        }
    }

    #[test]
    fn every_descriptor_fits_its_parameter_block() {
        for p in PROFILES {
            for c in (p.cmd)() {
                for f in c.fds {
                    assert!(
                        f.at + 4 <= c.params_size as usize,
                        "{} command {:#x}: descriptor at {} does not fit {} bytes",
                        p.version,
                        c.num,
                        f.at,
                        c.params_size
                    );
                    if let Some(h) = f.handle {
                        assert!(
                            h + 4 <= c.params_size as usize,
                            "{} command {:#x}: handle at {h} does not fit {} bytes",
                            p.version,
                            c.num,
                            c.params_size
                        );
                        assert_ne!(h, f.at, "the handle and the descriptor cannot be one field");
                    }
                }
            }
        }
    }

    /// The flags the backend sends have to be flags the release defines.
    /// Sending a bit outside the mask is sending a bit that means nothing --
    /// or, worse, something else later.
    #[test]
    fn the_flags_we_send_are_flags_the_release_has() {
        for p in PROFILES {
            let f = (p.init)();
            assert_eq!(
                f.ours() & !f.mask,
                0,
                "{} sends a bit outside its mask",
                p.version
            );
            assert!(
                f.ours() & f.multi_process_sharing_mode != 0,
                "{} does not get sharing mode, and the backend holds one UVM file for every guest process",
                p.version
            );
        }
    }

    /// The releases genuinely differ here, and the whole point of reading the
    /// flags per release rather than writing them down is that 535.129.03 has
    /// no bit for pageable access. If that stops being true this test should
    /// fail rather than quietly stop testing anything.
    #[test]
    fn the_older_releases_cannot_ask_for_pageable_access_to_be_off() {
        let old = select(v(535, 129, 3)).unwrap();
        assert!(!old.init.can_disable_pageable_access());
        assert!(old.pageable_must_be_off());
        assert_eq!(old.init.mask, 0x3);

        let new = select(v(615, 71, 9)).unwrap();
        assert!(new.init.can_disable_pageable_access());
        assert!(!new.pageable_must_be_off());
        assert_eq!(new.init.mask, 0x7);
        assert!(new.init_flags() & new.init.disable_pageable_access.unwrap() != 0);
    }

    #[test]
    fn an_exact_table_is_the_release_s_own() {
        for want in supported_versions() {
            let s = select(want).expect("a release with a table selects it");
            assert!(s.exact, "{want}");
        }
    }

    #[test]
    fn an_unknown_release_falls_back_and_says_so() {
        assert!(select(v(500, 0, 0)).is_none(), "older than every table");
        let s = select(v(615, 80, 0)).expect("newer than every table falls back");
        assert!(!s.exact);
    }

    /// On a fallback a command the releases describe differently is refused.
    /// UVM's parameter structs grow, and a descriptor read at the offset an
    /// older release gave is read out of the wrong four bytes.
    #[test]
    fn a_fallback_needs_every_release_to_agree() {
        let differs = v615_71_09::CMD
            .iter()
            .find(|c| PROFILES.iter().any(|p| find((p.cmd)(), c.num) != Some(c)))
            .expect("the releases differ somewhere");
        assert!(select(v(615, 71, 9)).unwrap().entry(differs.num).is_some());
        assert!(select(v(615, 80, 0)).unwrap().entry(differs.num).is_none());
    }

    /// ...and one they agree on survives, or the rule above refuses everything.
    #[test]
    fn a_fallback_still_permits_what_every_release_agrees_on() {
        let same = v615_71_09::CMD
            .iter()
            .find(|c| PROFILES.iter().all(|p| find((p.cmd)(), c.num) == Some(*c)))
            .expect("the releases agree somewhere");
        assert!(select(v(615, 80, 0)).unwrap().entry(same.num).is_some());
    }

    /// The descriptor-carrying commands, named. A descriptor the table does
    /// not know about is one the backend forwards as the guest's own number,
    /// so this pins the set rather than trusting it to stay the same.
    #[test]
    fn the_commands_that_carry_a_descriptor() {
        let s = select(v(615, 71, 9)).unwrap();
        let carrying: Vec<_> = s.cmd.iter().filter(|c| !c.fds.is_empty()).collect();
        assert_eq!(carrying.len(), 8, "615.71.09 carries eight");

        // UVM_REGISTER_GPU_VASPACE: a control descriptor and the client handle
        // it indexes, four bytes apart, after the 16-byte UUID.
        let e = s.entry(25).expect("UVM_REGISTER_GPU_VASPACE");
        assert_eq!(e.fds, &[FdSlot::new(Fd::Ctl, 16, Some(20))]);

        // UVM_IMPORT_DMA_BUF: a descriptor for something this backend never
        // opened, and so no handle beside it.
        let e = s.entry(83).expect("UVM_IMPORT_DMA_BUF");
        assert_eq!(e.fds, &[FdSlot::new(Fd::Foreign, 16, None)]);

        // UVM_MM_INITIALIZE takes a UVM descriptor, not a control one.
        let e = s.entry(75).expect("UVM_MM_INITIALIZE");
        assert_eq!(e.fds, &[FdSlot::new(Fd::Uvm, 0, None)]);
    }
}
